mapper.select:
SELECT tdm08_company_id
  FROM tdm08_manager_info
 WHERE tdm08_manager_info_id = #{managerInfoId}

mapper.update:
UPDATE tdm08_manager_info
   SET tdm08_person_id  = #{row.personId}
     , tdm08_start_date = #{row.startDate}
     , tdm08_end_date   = #{row.endDate}
     , tdm08_upd_nm     = #{updName}
     , tdm08_upd_date   = f_sysdate()
 WHERE tdm08_manager_info_id = #{row.managerInfoId}

mapper.delete:
DELETE FROM tdm08_manager_info
 WHERE tdm08_company_id = #{companyId}
   AND tdm08_manager_info_id IN
#{id}
